CREATE TABLE quality_verifications(`id` bigint  UNSIGNED PRIMARY KEY AUTO_INCREMENT,`created_at` timestamp  DEFAULT CURRENT_TIMESTAMP NOT NULL,`updated_at` timestamp  DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP NOT NULL,`enable` TINYINT(1)  NOT NULL  DEFAULT 1 ,`booking_id` BIGINT  NOT NULL,`verification_date` timestamp  NOT NULL DEFAULT CURRENT_TIMESTAMP,`verifier_type` varchar(50)  NOT NULL,`quality_grade` varchar(10)  NOT NULL,`quality_metrics` text  NULL,`photos` text  NULL,`passed` TINYINT(1)  NOT NULL DEFAULT 0,`notes` text  NULL)ENGINE = InnoDB AUTO_INCREMENT = 1 DEFAULT CHARSET = utf8;